"use client";

import { useState } from "react";
import { motion } from "framer-motion";

const data = [
  {
    name: "Imamudin",
    role: "Ortu. Ananda Anam",
    rating: 5,
    testimonial:
      "Terkait pembelajaran yang disampaikan oleh Sekolah Developer Indonesia itu jauh diluar bayangan saya, saya senang menemukan sekolah ini. Semoga istiqomah.",
  },
  {
    name: "Aisyah Binti Imamudin",
    role: "Ortu. Ananda Budi",
    rating: 4,
    testimonial:
      "Terkait pembelajaran yang disampaikan oleh Sekolah Developer Indonesia itu jauh diluar bayangan saya, saya senang menemukan sekolah ini. Semoga istiqomah.",
  },
  {
    name: "Fauzi Ahmad",
    role: "Ortu. Ananda Citra",
    rating: 5,
    testimonial:
      "Terkait pembelajaran yang disampaikan oleh Sekolah Developer Indonesia itu jauh diluar bayangan saya, saya senang menemukan sekolah ini. Semoga istiqomah.",
  },
  {
    name: "Rina Sari",
    role: "Ortu. Ananda Dedi",
    rating: 4,
    testimonial:
      "Terkait pembelajaran yang disampaikan oleh Sekolah Developer Indonesia itu jauh diluar bayangan saya, saya senang menemukan sekolah ini. Semoga istiqomah.",
  },
  {
    name: "Budi Santoso",
    role: "Ortu. Ananda Eko",
    rating: 5,
    testimonial:
      "Terkait pembelajaran yang disampaikan oleh Sekolah Developer Indonesia itu jauh diluar bayangan saya, saya senang menemukan sekolah ini. Semoga istiqomah.",
  },
];

const CARD_WIDTH = 440;
const VISIBLE_CARDS = 3;

export default function Testimonial() {
  const [index, setIndex] = useState(0);
  const maxIndex = data.length - VISIBLE_CARDS;

  const next = () => {
    if (index < maxIndex) setIndex((prev) => prev + 1);
  };

  const prev = () => {
    if (index > 0) setIndex((prev) => prev - 1);
  };

  return (
    <main className="relative bg-black min-h-screen m-7 rounded-3xl p-20 overflow-hidden">
      {/* HEADER */}
      <div className="flex justify-between items-start mb-16">
        <div>
          <h1 className="text-5xl font-bold text-white mb-4">
            Apa kata mereka?
          </h1>
          <p className="text-gray-300 text-lg max-w-xl">
            Berikut adalah testimonial dari orang tua siswa yang telah mengikuti
            program kami.
          </p>
        </div>

        <div className="flex gap-4">
          <button
            onClick={prev}
            disabled={index === 0}
            className={`w-14 h-14 rounded-full bg-white text-black flex items-center justify-center
              ${index === 0 ? "opacity-40 cursor-not-allowed" : ""}`}
          >
            ←
          </button>

          <button
            onClick={next}
            disabled={index === maxIndex}
            className={`w-14 h-14 rounded-full bg-white text-black flex items-center justify-center
              ${index === maxIndex ? "opacity-40 cursor-not-allowed" : ""}`}
          >
            →
          </button>
        </div>
      </div>

      {/* SLIDER */}
      <div className="relative overflow-hidden">
        <motion.div
          animate={{ x: -index * CARD_WIDTH }}
          transition={{ type: "spring", stiffness: 120, damping: 20 }}
          className="flex gap-5"
        >
          {data.map((item, i) => (
            <div
              key={i}
              className="w-[420px] h-[360px] bg-white rounded-3xl p-8 shadow-lg shrink-0"
            >
              {/* HEADER */}
              <div className="flex items-center gap-4 h-[72px]">
                <div className="w-14 h-14 rounded-full bg-gray-200" />
                <div className="overflow-hidden">
                  <h3 className="font-bold text-lg text-black line-clamp-1">
                    {item.name}
                  </h3>
                  <p className="text-sm text-gray-600 line-clamp-1">
                    {item.role}
                  </p>
                </div>
              </div>

              {/* RATING */}
              <div className="mt-4 h-[28px] text-yellow-400">
                {"⭐".repeat(item.rating)}
              </div>

              {/* TESTIMONIAL */}
              <p className="mt-4 text-black text-sm leading-relaxed line-clamp-4">
                {item.testimonial}
              </p>
            </div>
          ))}
        </motion.div>
      </div>
    </main>
  );
}
